// Embeds templates/runner/*.ts into src/templates.generated.ts so the (browser-safe) renderer can emit them.
// Run with `pnpm --filter @gamex/specpack gen:templates`; a test fails when the generated file is stale.
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';

const dir = new URL('../templates/runner/', import.meta.url);
const files = readdirSync(dir)
  .filter((f) => f.endsWith('.ts'))
  .sort();
const entries = files.map(
  (f) =>
    `  ${JSON.stringify(`tests/runner/${f}`)}: ${JSON.stringify(readFileSync(new URL(f, dir), 'utf8'))},`,
);
const out = `// Generated by scripts/embed-templates.mjs from templates/runner — do not edit.\nexport const TEMPLATES: Readonly<Record<string, string>> = {\n${entries.join('\n')}\n};\n`;
writeFileSync(new URL('../src/templates.generated.ts', import.meta.url), out);
console.error(`embedded ${String(files.length)} template(s)`);
